// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guess, uint256 startBlock) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        startBlock = bound(startBlock, 256, type(uint64).max / 2);

        vm.roll(startBlock);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // target block stored by a correct contract is startBlock + 1;
        // settle() requires block.number > target, i.e. startBlock + 2 suffices.
        vm.roll(startBlock + 2);

        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }

        assertTrue(ok, "settle must succeed two blocks after lockInGuess");
    }
}
